 const skins=WEBTHEN_RADIO_SKINS,box=document.querySelector('#webthen-music'),main=box.querySelector('.music-main'),volume=document.querySelector('#music-volume'),station=document.querySelector('#music-station');
 const wrap=document.createElement('div');wrap.className='radio-skin-face-wrap';wrap.innerHTML='<div class="radio-skin-face"><div class="skin-title-art"></div><div class="skin-state-display"><strong>PAUSED</strong><small>LIVE STATION</small></div><div class="skin-station-title"></div><div class="skin-live-indicator">LIVE RADIO</div><div class="skin-volume-art"></div><input class="skin-volume" type="range" min="0" max="100" aria-label="Radio volume"><div class="skin-transports"></div><button type="button" class="skin-choose">Skins</button><button type="button" class="skin-list">List</button><button type="button" class="skin-follow">Follow era</button><button type="button" class="skin-source">Source</button><button type="button" class="skin-mini" aria-label="Minimize music player"></button><button type="button" class="skin-shade" aria-label="Fold music player"></button><button type="button" class="skin-close" aria-label="Turn off radio"></button></div>';main.prepend(wrap);
 const face=wrap.querySelector('.radio-skin-face'),nativeVolume=wrap.querySelector('.skin-volume');
 const picker=document.createElement('dialog');picker.id='radio-skin-picker';picker.setAttribute('aria-labelledby','radio-skin-heading');picker.innerHTML='<header><strong id="radio-skin-heading">Choose a ThenAmp skin</strong><button type="button" aria-label="Close skin picker">×</button></header><div class="skin-picker-content"><p>A few familiar designs from the museum’s most-downloaded list.</p><div class="skin-picker-grid"></div><button type="button" class="skin-webthen-original">Use WebThen original</button><p class="skin-picker-note">Original skin artwork adapted to WebThen’s live radio controls. EQ, track seeking, and song playlists are not provided.</p></div>';document.body.append(picker);
 const launch=document.createElement('button');launch.id='music-skins';launch.type='button';launch.textContent='Skins ▾';launch.title='Choose a ThenAmp skin';launch.setAttribute('aria-controls','radio-skin-picker');box.querySelector('#music-drag').insertBefore(launch,document.querySelector('#music-minimize'));launch.onclick=()=>{if(!picker.open)picker.showModal()};picker.querySelector('header button').onclick=()=>picker.close();
 function forward(selector){document.querySelector(selector).click()}
 const transports=[['Previous hits station',0,23,16,'#music-prev'],['Play live radio',23,23,39,'#music-play'],['Pause live radio',46,23,62,'#music-pause'],['Stop live radio',69,23,85,'#music-pause'],['Next hits station',92,22,108,'#music-next']];
 for(const [label,sprite,width,left,target]of transports){const b=document.createElement('button');b.type='button';b.className='skin-transport';b.setAttribute('aria-label',label);b.title=label;b.style.cssText='left:'+left+'px;width:'+width+'px;--sprite-x:-'+sprite+'px';b.onclick=()=>forward(target);wrap.querySelector('.skin-transports').append(b)}
 wrap.querySelector('.skin-mini').onclick=wrap.querySelector('.skin-shade').onclick=()=>forward('#music-minimize');wrap.querySelector('.skin-close').onclick=()=>forward('#music-close');wrap.querySelector('.skin-choose').onclick=()=>launch.click();wrap.querySelector('.skin-list').onclick=()=>station.focus();wrap.querySelector('.skin-follow').onclick=()=>forward('#music-follow');wrap.querySelector('.skin-source').onclick=()=>forward('#music-source');
 nativeVolume.oninput=()=>{volume.value=nativeVolume.value;volume.dispatchEvent(new Event('input',{bubbles:true}));refresh()};volume.addEventListener('input',refresh);station.addEventListener('change',refresh);document.querySelector('#music-follow').addEventListener('change',refresh);
 let current=null;
 function refresh(){const value=document.querySelector('#music-indicator').textContent;wrap.querySelector('.skin-state-display strong').textContent=value==='PLAY'?'LIVE':value;wrap.querySelector('.skin-state-display').title=value;wrap.querySelector('.skin-station-title').textContent=document.querySelector('#music-track').textContent;wrap.querySelector('.skin-station-title').title=document.querySelector('#music-year').textContent;wrap.querySelector('.skin-live-indicator').textContent=value==='PLAY'?'LIVE RADIO':'RADIO · '+value;const follow=document.querySelector('#music-follow').checked;wrap.querySelector('.skin-follow').setAttribute('aria-pressed',String(follow));nativeVolume.value=volume.value;wrap.querySelector('.skin-volume-art').style.backgroundPosition='0px -'+Math.round(Number(volume.value)/100*27)*15+'px';for(const b of picker.querySelectorAll('[data-skin]'))b.setAttribute('aria-pressed',String(b.dataset.skin===current?.id));picker.querySelector('.skin-webthen-original').setAttribute('aria-pressed',String(!current));}
 function apply(id,remember=true){current=skins.find(s=>s.id===id)||null;box.dataset.radioSkin=current?.id||'webthen';box.classList.toggle('has-radio-skin',!!current);if(current){for(const [key,value]of Object.entries(current.palette))box.style.setProperty('--radio-skin-'+key,value);face.style.backgroundImage='url("'+current.images.main+'")';wrap.querySelector('.skin-title-art').style.backgroundImage='url("'+current.images.titlebar+'")';for(const b of wrap.querySelectorAll('.skin-transport'))b.style.backgroundImage='url("'+current.images.cbuttons+'")';wrap.querySelector('.skin-volume-art').style.backgroundImage='url("'+current.images.volume+'")';}else for(const key of ['panel','text','lcd','ink','edge'])box.style.removeProperty('--radio-skin-'+key);if(remember)try{localStorage.setItem('webthen-radio-skin-v1',current?.id||'webthen')}catch(e){}refresh();}
 for(const s of skins){const b=document.createElement('button');b.type='button';b.className='skin-pick';b.dataset.skin=s.id;b.setAttribute('aria-label','Use '+s.name+' skin');const preview=document.createElement('img');preview.src=s.preview;preview.alt=s.name+' skin preview';const title=document.createElement('strong');title.textContent=s.name;const caption=document.createElement('small');caption.textContent=s.description;b.append(preview,title,caption);b.onclick=()=>{apply(s.id);picker.close();launch.focus()};picker.querySelector('.skin-picker-grid').append(b)}
