 const legacy={graphite:'classic',midnight:'classified',copper:'sony',pocket:'ampboy',sky:'xp',glacier:'mac'};let saved='classic';try{saved=localStorage.getItem('webthen-radio-skin-v1')||'classic'}catch(e){}apply(legacy[saved]||saved,false);
